args.CodeContent:
"$path = "$env:USERPROFILE\.gemini\antigravity\brain\6768435f-eb70-4e50-a228-092414afb636\.system_generated\logs\transcript.jsonl"
if (Test-Path $path) {
    Write-Host "Found transcript.jsonl at $path"
    $lines = Get-Content $path -Encoding UTF8
    foreach ($line in $lines) {
        if ($line -like "*index.html*") {
            try {
                $obj = ConvertFrom-Json $line
                $stepVal = $obj.step_index
                $typeVal = $obj.type
                Write-Host "Step $stepVal - Type: $typeVal"
                if ($line -like "*replace_file_content*" -or $line -like "*write_to_file*") {
                    $outPath = "scratch_raw_step_${stepVal}.json"
                    $line | Out-File -FilePath $outPath -Encoding utf8
                    Write-Host "  Dumped raw JSON to $outPath"
                }
            } catch {
                Write-Host "Failed to parse JSON for a line containing index.html"
            }
        }
    }
} else {
    Write-Host "Not found"
}
"
